/**
 * Keyed for single-pass lookup, but multi-valued on purpose.
 *
 * A label like "liga 1" names a different competition in every country that
 * uses the word, and the capture confirms it against "league one", "ligue 1",
 * "1 lyga" and "primera division". Collapsing a label to a single canonical
 * partner would drop three of those, and taking whichever appeared first would
 * make the choice arbitrary. Keeping the full set preserves every proven
 * pairing, and a match succeeds when each label appears in the other's set:
 * "liga 1"/"ligue 1" pair, while "liga 1"/"liga 2" do not.
 *
 * @type {Map<string, Set<string>>}
 */
export const TRANSLATION_INDEX = (() => {
  const index = new Map();
  const add = (from, to) => {
    if (!index.has(from)) index.set(from, new Set());
    index.get(from).add(to);
  };
  for (const [a, b] of LEAGUE_TRANSLATIONS) {
    add(a, b);
    add(b, a);
  }
  return index;
})();
